package com.jgeted.sagadyssey.social.war;
import com.jgeted.sagadyssey.social.war.api.*;
import com.jgeted.sagadyssey.social.war.domain.*;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class WarEngineeringProgramTest{
    static WarIntent.Position p(int x,int y,int z){return new WarIntent.Position(WarKey.parse("minecraft:overworld"),x,y,z);}
    static WarEngineeringJob job(WarEngineeringLayouts.Layout l){var old=WarEngineeringRulesTest.job();var first=l.program().steps().getFirst();var cells=new ArrayList<WarEngineeringJob.Cell>();
        for(int i=0;i<l.targets().size();i++)cells.add(new WarEngineeringJob.Cell(l.targets().get(i),WarEngineeringJob.UNOBSERVED,first.mode()==WarEngineeringJob.Mode.DIG?"air":"target",20));
        return new WarEngineeringJob(old.id(),old.army(),old.owner(),old.service(),old.person(),old.body(),first.mode(),first.material(),cells,old.phase(),0,Set.of(),100,1,100,false,"player-selected route",Optional.of(l.program()));}
    @Test void spikePitsUseBankStandsAndOnlyOneRealSpikePerColumn(){var l=WarEngineeringLayouts.trap(WarEngineeringProgram.Kind.SPIKE_PIT,p(0,10,0),p(7,10,0),1);var j=job(l);assertEquals(24,j.cells().size());assertEquals(8,l.program().steps().stream().filter(s->s.material().isPresent()).count());assertEquals(p(0,11,1),l.program().steps().getFirst().stand());assertEquals(l.targets().get(1),l.targets().get(2));}
    @Test void websAreFiniteAboveGroundPlacements(){var l=WarEngineeringLayouts.trap(WarEngineeringProgram.Kind.WEB_SNARE,p(0,11,0),p(0,11,2),-1);assertEquals(3,job(l).cells().size());assertTrue(l.program().steps().stream().allMatch(s->s.material().orElseThrow().toString().equals("minecraft:cobweb")));}
    @Test void tunnelWorksFromPreviousSectionAndSupportsBeforeAdvancing(){var l=WarEngineeringLayouts.tunnel(p(0,10,0),p(2,10,0),p(2,10,2));var j=job(l);assertEquals(16,j.cells().size());assertEquals(List.of(p(1,11,0),p(1,10,0),p(1,12,0),p(1,12,0)),l.targets().subList(0,4));assertEquals(p(1,10,0),l.program().steps().get(4).stand());assertEquals(4,l.program().steps().stream().filter(s->s.material().isPresent()).count());}
    @Test void sizeCoordinatesDiagonalSlopesAndLoopsAreRejectedBeforeWorldAccess(){assertThrows(IllegalArgumentException.class,()->WarEngineeringLayouts.tunnel(p(0,0,0),p(17,0,0),p(17,0,0)));assertThrows(IllegalArgumentException.class,()->WarEngineeringLayouts.tunnel(p(0,0,0),p(1,1,0),p(2,1,0)));assertThrows(IllegalArgumentException.class,()->WarEngineeringLayouts.tunnel(p(0,0,0),p(2,0,0),p(0,0,0)));assertThrows(IllegalArgumentException.class,()->WarEngineeringLayouts.trap(WarEngineeringProgram.Kind.SPIKE_PIT,p(0,0,0),p(1,0,1),1));assertThrows(IllegalArgumentException.class,()->WarEngineeringLayouts.trap(WarEngineeringProgram.Kind.WEB_SNARE,p(0,0,0),p(8,0,0),1));assertThrows(IllegalArgumentException.class,()->WarEngineeringLayouts.offset(p(30_000_000,0,0),1,0,0));}
    @Test void maximumTunnelHasExactlySixtyFourSteps(){assertEquals(64,job(WarEngineeringLayouts.tunnel(p(0,0,0),p(8,0,0),p(8,0,8))).cells().size());}
    @Test void hiddenFaceCannotProduceAnIntentOrAReceipt(){var j=job(WarEngineeringLayouts.tunnel(p(0,0,0),p(1,0,0),p(1,0,0)));assertTrue(j.unobserved());assertThrows(IllegalArgumentException.class,()->j.change(WarEngineeringJob.Phase.ISSUING,101,"cannot issue hidden face"));assertThrows(IllegalArgumentException.class,()->j.completeCell(101,"no original receipt"));}
    @Test void onlyCurrentFaceCanBeRevealedAndFutureRemainsUnknown(){var j=job(WarEngineeringLayouts.tunnel(p(0,0,0),p(2,0,0),p(2,0,0)));var c=j.cells().getFirst();var seen=j.observeCell(new WarEngineeringJob.Cell(c.position(),"stone",c.after(),75),101,"actual exposed face");assertTrue(WarEngineeringJob.follows(j,seen));assertFalse(seen.unobserved());assertTrue(seen.cells().subList(1,8).stream().allMatch(x->x.before().equals(WarEngineeringJob.UNOBSERVED)));var next=j.cells().get(1);assertThrows(IllegalArgumentException.class,()->j.observeCell(new WarEngineeringJob.Cell(next.position(),"stone",next.after(),75),101,"future peek"));assertThrows(IllegalArgumentException.class,()->seen.observeCell(c,102,"rewrite observed face"));}
    @Test void existingAirOrSupportIsAnExplicitNoEffectAdoption(){var j=job(WarEngineeringLayouts.tunnel(p(0,0,0),p(1,0,0),p(1,0,0)));var next=j.adoptCell(101,"existing target, no goods or credit");assertEquals(Set.of(0),next.adopted());assertTrue(WarEngineeringJob.follows(j,next));assertTrue(next.cells().getFirst().before().equals(WarEngineeringJob.UNOBSERVED));}
    @Test void modifiedTemplateCannotSmuggleAnArbitraryExcavationRoute(){var l=WarEngineeringLayouts.tunnel(p(0,0,0),p(2,0,0),p(2,0,0));var j=job(l);var cells=new ArrayList<>(j.cells());var c=cells.get(3);cells.set(3,new WarEngineeringJob.Cell(p(1,0,1),c.before(),c.after(),c.workTicks()));assertThrows(IllegalArgumentException.class,()->l.program().validate(cells,j.army()));}
    @Test void disarmRequiresTheSameArmyAndExactObservedPosition(){var base=WarEngineeringRulesTest.job();var o=new WarHazardObservation(UUID.randomUUID(),base.army(),base.person(),base.body(),p(1,0,0),WarKey.parse("sagadyssey:war/hazard/web"),"cobweb",100,WarHazardObservation.Source.SURVEY);var l=WarEngineeringLayouts.disarm(o,p(0,0,0));var cells=List.of(new WarEngineeringJob.Cell(o.position(),WarEngineeringJob.UNOBSERVED,"air",20));assertDoesNotThrow(()->l.program().validate(cells,base.army()));assertThrows(IllegalArgumentException.class,()->l.program().validate(cells,UUID.randomUUID()));}
}
